import { MakeLogicType, afterMount, kea, path } from 'kea'
import { router, urlToAction } from 'kea-router'

import { urls } from 'scenes/urls'

import { getEvaluationsEntryRedirect } from './evaluationsEntryRedirect'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export type evaluationsEntryLogicType = MakeLogicType<{}, {}>

export const evaluationsEntryLogic = kea<evaluationsEntryLogicType>([
    path(['products', 'ai_observability', 'frontend', 'evaluations', 'evaluationsEntryLogic']),
    urlToAction(() => ({
        [urls.aiObservabilityEvaluations()]: (_, searchParams) => {
            const redirect = getEvaluationsEntryRedirect(searchParams)
            if (redirect) {
                router.actions.replace(redirect)
            }
        },
    })),
    afterMount(() => {
        const redirect = getEvaluationsEntryRedirect(router.values.searchParams)
        if (redirect) {
            router.actions.replace(redirect)
        }
    }),
])
